mapper.select:
SELECT ta.id as appointment_id, ta.name, ta.sex, ta.tel, ta.birthday, ta.status as appointment_status, ta.appointment_date, cr.id as report_id, cr.result_id, cr.status, cr.file_path, cr.generated_time, cr.waybill_code, cr.waybill_date FROM tb_checkup_report cr LEFT JOIN tb_appointment ta on cr.appointment_id = ta.id
AND ta.name LIKE CONCAT('%', #{request.name}, '%')
AND ta.tel = #{request.tel}
AND cr.waybill_code = #{request.waybillCode}
AND cr.status = #{request.status}
ORDER BY cr.id DESC

SELECT COUNT(*)
FROM tb_checkup_report r


        AND EXISTS (
        SELECT 1
        FROM tb_appointment a
        WHERE a.id = r.appointment_id

            AND a.name LIKE CONCAT('%', #{request.name}, '%')


            AND a.tel = #{request.tel}

        )



        AND r.waybill_code = #{request.waybillCode}


        AND r.status = #{request.status}

SELECT r.id, r.appointment_id, r.result_id, r.date
FROM tb_appointment a
         INNER JOIN tb_checkup_report r ON a.id = r.appointment_id
WHERE a.status = #{appointmentStatus}
  AND r.status = #{reportStatus}
  and a.completed_time >= #{startDateTime}
  and a.completed_time < #{endDateTime}
  AND a.is_deleted = 0
    /* 过滤掉最近 24 小时内失败过的记录，避免每次执行定时任务时都重试 */
  AND (r.error_time IS NULL OR r.error_time < DATE_SUB(NOW(), INTERVAL 24 HOUR))
ORDER BY a.completed_time, r.id
LIMIT #{limit}
